python3 -I - 06936a98* 0bfaa72b* 632806b9* 96a18d56* a69ae69c* c447868d* <<'EOF'
import json,sys,re
pat=re.compile(r'(ssid|wpa_passphrase|passphrase|password|passwd|api[_ -]?key|secret|token=|\.env\b|ssh |known_hosts|id_rsa|/etc/shadow|phone|address)',re.I)
def texts(o):
    if isinstance(o,str): yield o
    elif isinstance(o,list):
        for x in o: yield from texts(x)
    elif isinstance(o,dict):
        for k,v in o.items():
            if k in('signature','tools','system'):continue
            yield from texts(v)
for f in sys.argv[1:]:
    hits={}
    for line in open(f,errors='replace'):
        try:d=json.loads(line)
        except: continue
        if d.get('type') not in('user','assistant'):continue
        for t in texts(d.get('message',{}).get('content')):
            for m in pat.finditer(t):
                s=t[max(0,m.start()-50):m.end()+50].replace('\n',' ')
                hits.setdefault(m.group(1).lower(),set()).add(s)
    print('==',f)
    for k,v in hits.items():
        print(f'  [{k}] {len(v)} unique; e.g.:')
        for s in list(v)[:3]: print('     ',s)
EOF

